addon_table.spoken_bosses_uk = {
    [33] = {
        ["archmage arugal"] = [[Аруґал був даларанським магом із Кірін-Тору й носив титул архімага. Далар Давнвівер, маг Кірін-Тору, який згодом посів високе місце серед Відречених, згадує його як шарлатана. Каже, що хитрощі Аруґала були такі прозорі, що йому в Даларані не доручили б навіть мити нічні горщики, а свою слабку магію він підсилював зачарованими предметами.

Коли прийшла Скара, Аруґал випустив ворґенів, щоб допомогти магам Кірін-Тору в боротьбі з невмерлими. Звірі вийшли з-під його влади й почали поширювати прокляття. Вони захопили фортецю барона Срібляра над селом Поховальні Вогнища й убили самого барона. Збожеволівши від почуття провини, Аруґал прийняв ворґенів як власних дітей і перейменував твердиню на фортецю Тіньового Ікла.

Звідти він поширював прокляття Срібнохвойним пралісом. Воно вразило зграї Місяцесказу й Тіньового Ікла та мешканців Поховальних Вогнищ. Кірін-Тор надіслав чаклуна Золомбі перевірити, як Аруґал бореться з невмерлими, а Відречені тепер прагнуть його смерті. У своєму кабінеті Аруґал досі зберігає книгу Ура, даларанського мага, який досліджував інші світи.]],
        ["baron silverlaine"] = [[Барон Срібляр володів фортецею над селом Поховальні Вогнища. Тоді її звали фортецею Срібляра. Барон жив там зі своїм почтом і воїнами, доки ворґени архімага Аруґала не прорвалися за мури й не вбили його.

Смерть не звільнила барона. Його проклятий привид досі блукає обідньою залою в супроводі кількох слуг. Кожного чужинця, який заходить до його дому, він вважає порушником, якого слід покарати.]],
        ["commander springvale"] = [[Командир Джерельний був паладином Срібної Десниці й очолював воїнів, які служили баронові Срібляру. Коли ворґени захопили фортецю Тіньового Ікла, він поліг разом із підлеглими.

Його привид блукає радною залою, і воїни досі поруч із ним. Навіть смерть не поклала край його відданості. Заради свого колишнього пана Джерельний боронить залу від кожного, хто заходить до неї.]],
        ["fenrus the devourer"] = [[Фенрус — улюбленець архімага Аруґала, варґ неймовірних розмірів, що скрадається головним кабінетом архімага. Можливо, таким його зробили темні чари самого Аруґала або ворґенів, які йому служать.

Зачувши чужинця, Фенрус видає громовий рик, чутний у кожному закутку фортеці.]],
        ["odo the blindwatcher"] = [[Одо-Сліпогляд — ворґен зі зграї Тіньового Ікла, підлеглої Аруґалу. Він живе в хиткій дерев’яній споруді, що нависає зі стіни фортеці, і ділить її з двома ручними кажанами: Кровожадом і злісним кажаном.

Одо давно втратив зір, звідси й прізвисько. З роками він навчився покладатися на решту чуттів, як і його кажани.]],
        ["razorclaw the butcher"] = [[Бритвопал-М’ясник облаштував лігво в колишній кухні фортеці Тіньового Ікла. Коли його господар Аруґал привів його до фортеці, він повбивав там багато невинних людей. Саме та різанина й дала йому прізвисько.]],
        ["rethilgore"] = [[Ретілют, відомий як вартовий в’язниці, — один із найжорстокіших ворґенів у зграї архімага Аруґала. Аруґал довірив йому стерегти бранців фортеці Тіньового Ікла.

Серед них — смертолов Адамант, розвідник Відречених, якого верховний каратель Гадрек послав розвідати все, що можна, і чаклун Золомбі, посланець Кірін-Тору. Адамант потрапив в одну з магічних пасток Аруґала. Його кинули до камери, біля якої чатує Ретілют.]],
        ["wolf master nandos"] = [[Повелитель вовків Нандос — ворґен, якому підкоряються менші варґи на службі Аруґала. Він має власну зграю, що кидається на чужинців і не дає їм дістатися до нього.

Нандос — останній із посіпак, які заступають шлях до архімага.]],
    },
    [34] = {
        ["bazil thredd"] = [[Базіл Тредд був правою рукою Едвіна ван Кліфа й найдовіренішим його помічником у Братстві Непокірних. Його схопили й кинули до Штормовійської в’язниці. Багато місяців до нього ніхто не навідувався, і наглядачі вирішили, що Братство махнуло на нього рукою.

За кілька місяців до тюремного бунту Тредда почав відвідувати чоловік, який називався Маеліком. Він передавав звістки між Треддом, ван Кліфом і лордом Грегором Лесковаром із Палати шляхти. Тредд і Лесковар спланували повстання у в’язниці. Тепер Тредд очолює Непокірних серед в’язнів, і наглядач Телвотер жадає його голови.]],
        ["dextren ward"] = [[Декстрен Ворд походив зі Смерколісся. Його впіймали на продажі тіл із кладовища Воронячого пагорба некромантові Морбенту Скверну. Лорд Елло Чорнобривий і рада Темнодолу засудили його до страти. Однак Палата шляхти у Штормовії забрала в’язня собі й замкнула у в’язниці, не давши виконати вирок.

Мешканці Темнодолу сприйняли це як образу. Радник Млинченко вимагає руку Ворда на доказ того, що справедливість здійснилася, і каже, що знать ігнорує потреби Смерколісся. Коли у в’язниці спалахнув бунт, Ворд опинився серед його призвідців.]],
        ["hamhock"] = [[Голяш — двоголовий оґр, якого утримують у Штормовійській в’язниці. Коли в’язні повстали проти варти, він приєднався до ватажків бунту. Тепер він стереже залу з трьома камерами. У середній сидить Базіл Тредд.]],
        ["kam deepfury"] = [[Кам Темнолют — темнозалізний дворф. Розвідка Альянсу в Дун-Модрі вважає його організатором нападу на віадук Тандола. Вибух знищив один із двох великих мостів між Заболоттям і височиною Араті. Загинуло багато дворфів, серед них брат Довгокоса Похмурого.

Штормовій тримає Кама у в’язниці з політичних міркувань і досі його не стратив. На відміну від більшості тамтешніх в’язнів, він не належить до Братства Непокірних. Мотлі Гармаш із Дун-Модра жадає його смерті й звинувачує людську бюрократію в тому, що той досі живий.]],
        ["targorr the dread"] = [[Тарґорр Жахливий був головним катом Ґат'Ільзоґґа, воєводи орків Чорнокаменю в Багрянокряжових горах. Він катував людей, які відважно боронили королівство, за власною примхою й із такою жорстокістю, що навіть його одноплемінники жахалися.

Його схопили, відправили до Штормовійської в’язниці й засудили до страти. Один шляхтич призупинив виконання вироку, і мешканці Приозер'я підозрюють підступ. Коли в’язні повстали проти варти, Тарґорр пристав до бунтівників Непокірних.]],
    },
    [36] = {
        ["captain greenskin"] = [[Капітан Зеленошкір — гоблін із Бухти Наживи, де він колись командував флотилією піратських суден. Ван Кліф доручив йому командувати велетенським бойовим кораблем, який будують у Мертвих копальнях. Першим помічником Зеленошкіра служить Пан Бац, а на камбузі порядкує Кухарчик. Ван Кліф збирається з цього корабля спустошити Штормовій з моря.]],
        ["cookie"] = [[Кухарчик — мурлок, який служить корабельним коком на велетенському бойовому кораблі капітана Зеленошкіра й Едвіна ван Кліфа. Лише ван Кліф знає, як і чому Кухарчик дістав цю посаду. Пірати, схоже, не заперечують. Для них їжа є їжа.]],
        ["edwin vancleef"] = [[Едвін ван Кліф очолював Гільдію каменярів, чиї майстри відбудували Штормовій після того, як орки його спалили. Він виріс у місті й опанував ремесло пройдисвіта разом із другом дитинства Матіасом Гичем. Коли роботу скінчили, Палата шляхти відмовилася сплатити гільдії борг. Ван Кліф марно обстоював їхнє право на платню й вивів своїх послідовників із міста.

На пагорбах Західного краю він перетворив каменярів на Братство Непокірних, ватагу злодіїв і вбивць у червоних хустках. Вони зігнали селян із їхніх земель і захопили ферми та шахти по всьому Західному краю й Ельвинну. Ван Кліф осів у покинутих Мертвих копальнях під Місяцеграєм. Там інженери-гобліни будують великий корабель, щоб ударити по Штормовію з моря.

Він командує з каюти того корабля. Міський архітектор Барос Алексстон, його давній друг, пам’ятає його неперевершеним бійцем, ідеалістом і романтиком. Каже, що жадоба помсти поглинула його.]],
        ["gilnid"] = [[Ґілнід — вправний інженер-гоблін і головний ливарник Непокірних. Гобліни ван Кліфа звели в копальнях ливарню. Там Ґілнід перетворює сталь і мідь із захоплених шахт на якорі й ядра для велетенського корабля.

Він стежить, щоб на борту вистачало гармат і боєприпасів, і не дозволяє перепочинку, поки робота не скінчена.]],
        ["mr smite"] = [[Пан Бац — таурен, який служить першим помічником капітана Зеленошкіра. Він тримає команду в тонусі й майстерно володіє зброєю. Уміє рубати, трощити, а при нагоді й прострелити наскрізь.

Він полюбляє бавитися з жертвами. Спершу дає їм повірити, що вони можуть перемогти, а потім вихоплює дедалі небезпечнішу зброю: після злодійського клинка бере пару сікачів, а насамкінець — могутній молот.]],
        ["rhahkzor"] = [[Рак'Зор — оґр і головний десятник Братства Непокірних у Мертвих копальнях. Їх покинули, коли Штормовій упав під час Першої війни. Тепер Рак'Зор керує ними для Едвіна ван Кліфа й наглядає за його будівництвом. У печери везуть руду, деревину й метал із шахт і ферм, захоплених Братством у Західному краї й Ельвинні.

Робітники підпорядковуються Рак'Зору. Він «заохочує» їх працювати. Методи в нього своєрідні, зате дієві.]],
        ["sneed"] = [[Братство Непокірних найняло гобліна Сніда начальником лісозаготівлі за його безжальну діловитість. Він керує щогловою залою, де з деревини Західного краю роблять щогли й оснащення для велетенського бойового корабля ван Кліфа. Судно будують за зразком оркських кораблів Другої війни.

Його мета проста — збудувати корабель якнайдешевше. Для роботи він змайстрував собі подрібнювач деревини. Коли Снід сідає за кермо, робота йде зі страхітливою швидкістю.]],
    },
    [43] = {
        ["kresh"] = [[Чавк — велетенська старезна черепаха, що мандрує рікою й печерами біля входу до Плачучих печер. Кошмар Наралекса не зачепив тамтешніх черепах. Чавк із його стійким розумом не зважає на нього й живе собі, не помічаючи зла довкола. Вдача в нього весела.]],
        ["lady anacondra"] = [[Леді Анакондру колись звали Багрянолистою. Вона була молодою послушницею друїда Наралекса й першою зголосилася приєднатися до його походу в Степи. За допомогою Плачучих печер і Смарагдового Сну друїд сподівався знову вкрити цей край зеленню.

Коли сон Наралекса обернувся кошмаром, її розум не витримав. Вона відкинула старе ім’я і тепер бачить зловісне майбутнє, у якому Азеротом заволодіють плазуни. Вона одна з чотирьох очільників друїдів Ікла.]],
        ["lord cobrahn"] = [[Лорда Кобрана колись звали Джарлаксла. Його вміння набувати подоби звірів прославило його серед друїдів Кенарієвого Кола. Скверна Плачучих печер спотворила цей дар.

Він удосконалив свою смертоносну зміїну подобу й узяв ім’я Кобран, гідне його нової лютої сили. Він значно більший за інших друїдів, має пазур на правій руці й оточений спотвореними пітонами. Кобран — один із чотирьох очільників друїдів Ікла.]],
        ["lord pythas"] = [[Лорда Пітонаса колись звали Аріном. Він був другом дитинства Наралекса й досвідченим воїном у його особистій варті. Друїдські науки давалися йому легко, та вишкіл не вберіг його розуму від скверни.

Тепер він зветься Пітонасом і стоїть пліч-о-пліч із друїдами Ікла. Проти непроханих гостей він застосовує і друїдські чари, і своє вміння битися зблизька.]],
        ["lord serpentis"] = [[Лорд Серпентіс колись був найкращим учнем Наралекса. Він мріяв стати шан'до, шанованим учителем, як і його наставник. Це бажання й згубило його. Коли безумство вкоренилося в ньому, він згуртував довкола себе побратимів і заснував друїдів Ікла.

Колись цього могутнього друїда всі шанували. Тепер, спотворений кошмаром Наралекса, він очолює друїдів Ікла в глибинах печер, а його улюбленцем є громова ящірка Шкам.]],
        ["mutanus the devourer"] = [[Мутанус-Пожирач вийшов із найтемніших закутків спотвореного розуму Наралекса. Скверна, що мучить Смарагдовий Сон, прибрала подобу найлютішого ворога друїда — мурлока. У світ, де ніхто не спить, вона послала велетенського мурлока-альбіноса.

Хоч би яка сила отруїла сни Наралекса, вона звеліла Мутанусові перешкодити кожному, хто спробує його розбудити. Коли учень Наралекса починає обряд пробудження сплячого друїда, Мутанус з’являється, щоб пожерти тих, хто прийшов його звільнити.]],
        ["skum"] = [[Громова ящірка Шкам прийшла в Плачучі печери, шукаючи прихистку від суворих умов Степів. Як і багато інших мешканців печер, вона невдовзі піддалася скверні. Тепер у її жилах пульсує темна сила, яка зробила її могутнім, безжальним звіром, якого вже не врятувати. Шкама тримають у невеликому загоні у Звивистому проваллі як улюбленця лорда Серпентіса.]],
        ["verdan the everliving"] = [[Вердан Вічноживучий — велетенський елементаль, який давно виник із пишної рослинності Плачучих печер і охороняв їх. Про нього до появи Наралекса відомо небагато.

Вердан не зміг уникнути скверни, що поширилася його домівкою. Лагідний велетень став потворою, що тримається збожеволілих друїдів і чавить кожну живу істоту, яка підходить надто близько до його лігва.]],
    },
    [47] = {
        ["agathelos the raging"] = [[Агател Гнівний — велетенський закутий у броню вепр, удвічі більший за громову ящірку. У люті він стає ще більшим. Свинобрази шанують вепрів, а особливо великих і витривалих вважають знаком прихильності Аґамаґґана, велетенського вепра, бога й пращура свинобразів.

Мертвоголові тримають Агатела в короткому тунелі в краалі Бритвоболотих. Кілька свинобразів стережуть його й підтримують бар’єр, що не випускає звіра. І без того могутнього Агатела годували послідом тамтешніх кажанів. Від цього він шаленіє, міцніє й набирається витривалості. Мертвоголові хочуть обернути його на зброю проти всіх, хто стане їм на заваді.]],
        ["aggem thorncurse"] = [[Свинобрази здавна шанують шаманство. Найвидатніших шаманів племені називають пророками Аґамаґґана. Прикликаючи силу свого пращура-напівбога, вони кличуть на підмогу духів вепрів, як інші шамани кличуть вовчих духів.

